// Show every topic that has notes, narrowed by the search box and the two filter chips.
const topics = globalContext.tableViews['2e7e24ea-7339-4bca-954a-24f38b47379d']?.data || [];
const notes = globalContext.tableViews['7d4719cb-9d6a-48ce-9a85-4bf524fabe90']?.data || [];
const reviewed = variables['439e3f7b-f911-4841-9ef0-612168ab6596'] || {};
const search = String(variables['9448abac-a02c-439e-b949-99071f61b286-value'] || '').trim().toLowerCase();
let category = variables['2a35c43c-a0f5-4f62-adc5-3a3ead957664'] || 'All subjects';
const progress = variables['ede71345-55ed-4f23-990d-aaa2675f6cc9'] || 'All';

// Treat the old default label the same as All subjects.
if (category === 'All') category = 'All subjects';

const matching = topics.filter(function (topic) {
  const own = notes.filter(function (note) { return note?.topic_id === topic?.id; });
  if (!own.length) return false;

  if (search) {
    const haystack = (String(topic?.name || '') + ' ' + String(topic?.code || '')).toLowerCase();
    if (haystack.indexOf(search) === -1) return false;
  }

  if (category !== 'All subjects' && topic?.category !== category) return false;

  const done = own.filter(function (note) { return reviewed[note?.id]; }).length;
  if (progress === 'Not started' && done !== 0) return false;
  if (progress === 'In progress' && (done === 0 || done === own.length)) return false;
  if (progress === 'Reviewed' && done !== own.length) return false;

  return true;
});

return matching.sort(function (a, b) {
  return String(a?.code || '').localeCompare(String(b?.code || ''));
});

