// Offer one chip per subject strand that actually has notes, plus an "All subjects" reset.
const topics = globalContext.tableViews['2e7e24ea-7339-4bca-954a-24f38b47379d']?.data || [];
const notes = globalContext.tableViews['7d4719cb-9d6a-48ce-9a85-4bf524fabe90']?.data || [];

// Only consider topics that have at least one note section written.
const topicsWithNotes = topics.filter(function (topic) {
  return notes.some(function (note) { return note?.topic_id === topic?.id; });
});

const categories = [];
topicsWithNotes.forEach(function (topic) {
  const category = topic?.category;
  if (category && categories.indexOf(category) === -1) categories.push(category);
});

return ['All subjects'].concat(categories.sort());

